import type { CreateHost, Effect, Host, OrderView, Outcome } from '../host.ts';

const MAX_ITEMS = 3;

interface Order {
  status: OrderView['status'];
  items: number;
  charges: number;
  refunds: number;
}

const ok = (): Outcome => ({ ok: true });
const refuse = (reason: string): Outcome => ({ ok: false, reason });

const createHost: CreateHost = async () => {
  const orders = new Map<string, Order>();
  const pending = new Map<string, Effect>();
  let nextEffect = 1;

  const request = (from: string, kind: string, data: Record<string, unknown>) => {
    const id = `e${nextEffect++}`;
    pending.set(id, { id, from, kind, data });
  };

  const withOrder = (id: string, fn: (o: Order) => Outcome): Outcome => {
    const o = orders.get(id);
    return o ? fn(o) : refuse('unknown order');
  };

  const host: Host = {
    async create(id) {
      if (orders.has(id)) return refuse('order exists');
      orders.set(id, { status: 'draft', items: 0, charges: 0, refunds: 0 });
      return ok();
    },
    async addItem(id) {
      return withOrder(id, (o) => {
        if (o.status !== 'draft') return refuse('not a draft');
        if (o.items >= MAX_ITEMS) return refuse('draft is full');
        o.items++;
        return ok();
      });
    },
    async removeItem(id) {
      return withOrder(id, (o) => {
        if (o.status !== 'draft') return refuse('not a draft');
        if (o.items <= 0) return refuse('draft is empty');
        o.items--;
        return ok();
      });
    },
    async place(id) {
      return withOrder(id, (o) => {
        if (o.status !== 'draft') return refuse('not a draft');
        if (o.items <= 0) return refuse('draft is empty');
        o.status = 'placed';
        o.charges++;
        request(id, 'payment.charge', { amount: o.items });
        return ok();
      });
    },
    async ship(id) {
      return withOrder(id, (o) => {
        if (o.status !== 'paid') return refuse('not paid');
        o.status = 'shipped';
        return ok();
      });
    },
    async cancel(id) {
      return withOrder(id, (o) => {
        if (o.status === 'draft') {
          o.status = 'cancelled';
          return ok();
        }
        if (o.status === 'paid') {
          o.status = 'cancelled';
          o.refunds++;
          return ok();
        }
        return refuse(`cannot cancel a ${o.status} order`);
      });
    },
    async order(id) {
      const o = orders.get(id);
      return o ? { ...o } : null;
    },
    async pendingEffects() {
      return [...pending.values()].map((e) => ({ ...e, data: { ...e.data } }));
    },
    async completeEffect(id, outcome) {
      const e = pending.get(id);
      if (!e) return;
      pending.delete(id);
      if (e.kind !== 'payment.charge') return;
      const o = orders.get(e.from);
      if (!o || o.status !== 'placed') return;
      o.status = outcome === 'ok' ? 'paid' : 'failed';
    },
  };
  return host;
};

export default createHost;
EOF
cat > test/host.test.ts <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('happy path, refund', async () => {
  const h = await createHost();
  assert.equal((await h.addItem('a')).ok, false);
  assert.deepEqual(await h.create('a'), { ok: true });
  assert.equal((await h.create('a')).ok, false);
  assert.equal((await h.place('a')).ok, false);
  for (let i = 0; i < 3; i++) assert.equal((await h.addItem('a')).ok, true);
  assert.equal((await h.addItem('a')).ok, false);
  assert.equal((await h.removeItem('a')).ok, true);
  assert.equal((await h.place('a')).ok, true);
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal((await h.ship('a')).ok, false);
  const [e] = await h.pendingEffects();
  assert.deepEqual({ from: e.from, kind: e.kind, data: e.data }, { from: 'a', kind: 'payment.charge', data: { amount: 2 } });
  await h.completeEffect(e.id, 'ok');
  assert.deepEqual(await h.pendingEffects(), []);
  assert.deepEqual(await h.order('a'), { status: 'paid', items: 2, charges: 1, refunds: 0 });
  assert.equal((await h.cancel('a')).ok, true);
  assert.deepEqual(await h.order('a'), { status: 'cancelled', items: 2, charges: 1, refunds: 1 });
  assert.equal((await h.ship('a')).ok, false);
  assert.equal(await h.order('zz'), null);
});

test('failed charge, ship', async () => {
  const h = await createHost();
  await h.create('a'); await h.addItem('a'); await h.place('a');
  await h.create('b'); await h.addItem('b'); await h.place('b');
  const es = await h.pendingEffects();
  await h.completeEffect(es.find((e) => e.from === 'a')!.id, 'failed');
  await h.completeEffect(es.find((e) => e.from === 'b')!.id, 'ok');
  assert.equal((await h.order('a'))!.status, 'failed');
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal((await h.ship('b')).ok, true);
  assert.equal((await h.cancel('b')).ok, false);
  assert.equal((await h.order('b'))!.status, 'shipped');
});
EOF
