import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('happy path, refund', async () => {
  const h = await createHost();
  assert.equal((await h.addItem('a')).ok, false);
  assert.deepEqual(await h.create('a'), { ok: true });
  assert.equal((await h.create('a')).ok, false);
  assert.equal((await h.place('a')).ok, false);
  for (let i = 0; i < 3; i++) assert.equal((await h.addItem('a')).ok, true);
  assert.equal((await h.addItem('a')).ok, false);
  assert.equal((await h.removeItem('a')).ok, true);
  assert.equal((await h.place('a')).ok, true);
  assert.equal((await h.ship('a')).ok, false);
  const [e] = await h.pendingEffects();
  assert.deepEqual({ from: e.from, kind: e.kind, data: e.data }, { from: 'a', kind: 'payment.charge', data: { amount: 2 } });
  await h.completeEffect(e.id, 'ok');
  assert.deepEqual(await h.pendingEffects(), []);
  assert.deepEqual(await h.order('a'), { status: 'paid', items: 2, charges: 1, refunds: 0 });
  assert.equal((await h.cancel('a')).ok, true);
  assert.deepEqual(await h.order('a'), { status: 'cancelled', items: 2, charges: 1, refunds: 1 });
  assert.equal((await h.ship('a')).ok, false);
  assert.equal(await h.order('zz'), null);
});

test('cancel while placed', async () => {
  const h = await createHost();
  for (const id of ['a', 'b']) { await h.create(id); await h.addItem(id); await h.place(id); }
  assert.equal((await h.cancel('a')).ok, true);
  assert.equal((await h.cancel('b')).ok, true);
  assert.deepEqual(await h.order('a'), { status: 'cancelling', items: 1, charges: 1, refunds: 0 });
  for (const cmd of ['cancel', 'ship', 'place', 'addItem', 'removeItem', 'retryPayment'] as const)
    assert.equal((await h[cmd]('a')).ok, false, cmd);
  const es = await h.pendingEffects();
  await h.completeEffect(es.find((e) => e.from === 'a')!.id, 'ok');
  await h.completeEffect(es.find((e) => e.from === 'b')!.id, 'failed');
  assert.deepEqual(await h.order('a'), { status: 'cancelled', items: 1, charges: 1, refunds: 1 });
  assert.deepEqual(await h.order('b'), { status: 'cancelled', items: 1, charges: 1, refunds: 0 });
  assert.deepEqual(await h.pendingEffects(), []);
});

test('cancel during retry charge', async () => {
  const h = await createHost();
  await h.create('a'); await h.addItem('a'); await h.place('a');
  await h.completeEffect((await h.pendingEffects())[0].id, 'failed');
  await h.retryPayment('a');
  assert.equal((await h.cancel('a')).ok, true);
  await h.completeEffect((await h.pendingEffects())[0].id, 'failed');
  assert.deepEqual(await h.order('a'), { status: 'cancelled', items: 1, charges: 2, refunds: 0 });
});

test('retry succeeds, then refund on cancel', async () => {
  const h = await createHost();
  await h.create('a'); await h.addItem('a'); await h.place('a');
  await h.completeEffect((await h.pendingEffects())[0].id, 'failed');
  await h.retryPayment('a');
  await h.completeEffect((await h.pendingEffects())[0].id, 'ok');
  assert.equal((await h.cancel('a')).ok, true);
  assert.deepEqual(await h.order('a'), { status: 'cancelled', items: 1, charges: 2, refunds: 1 });
});

test('failed charge, ship', async () => {
  const h = await createHost();
  await h.create('a'); await h.addItem('a'); await h.place('a');
  await h.create('b'); await h.addItem('b'); await h.place('b');
  const es = await h.pendingEffects();
  await h.completeEffect(es.find((e) => e.from === 'a')!.id, 'failed');
  await h.completeEffect(es.find((e) => e.from === 'b')!.id, 'ok');
  assert.equal((await h.order('a'))!.status, 'declined');
  for (const cmd of ['cancel', 'ship', 'place', 'addItem', 'removeItem'] as const)
    assert.equal((await h[cmd]('a')).ok, false, cmd);
  assert.equal((await h.retryPayment('b')).ok, false);
  assert.equal((await h.retryPayment('a')).ok, true);
  assert.equal((await h.retryPayment('a')).ok, false);
  assert.deepEqual(await h.order('a'), { status: 'placed', items: 1, charges: 2, refunds: 0 });
  const [r] = await h.pendingEffects();
  assert.deepEqual([r.kind, r.from, r.data], ['payment.charge', 'a', { amount: 1 }]);
  assert.ok(!es.some((e) => e.id === r.id));
  await h.completeEffect(r.id, 'failed');
  assert.deepEqual(await h.order('a'), { status: 'failed', items: 1, charges: 2, refunds: 0 });
  assert.equal((await h.retryPayment('a')).ok, false);
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal((await h.ship('b')).ok, true);
  assert.equal((await h.cancel('b')).ok, false);
  assert.equal((await h.order('b'))!.status, 'shipped');
});

