  assert.equal((await h.release('a')).ok, true);
  assert.equal((await h.release('a')).ok, false);
  assert.equal((await h.ship('a')).ok, true);
  assert.equal((await h.hold('a')).ok, false);
  assert.deepEqual(await h.order('a'), { status: 'shipped', items: 1, charges: 1, refunds: 0, held: false });
});

test('cancel a held order', async () => {
  const h = await createHost();
  await paid(h, 'a');
  await h.hold('a');
  assert.equal((await h.cancel('a')).ok, true);
  assert.deepEqual(await h.order('a'), { status: 'cancelled', items: 1, charges: 1, refunds: 1, held: false });
  assert.equal((await h.release('a')).ok, false);
  assert.equal((await h.hold('a')).ok, false);
});

